import{_ as n,l as o,o as t,c as l,v as e,p as s,x as r,d as m,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"跳跃检验","description":"","frontmatter":{"title":"跳跃检验","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/jump-tests.md","filePath":"quant/jump-tests.md","lastUpdated":1789023840000}'),p={name:"quant/jump-tests.md"};function E(B,a,u,c,_,V){const i=o("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="跳跃检验" tabindex="-1">跳跃检验 <a class="header-anchor" href="#跳跃检验" aria-label="Permalink to &quot;跳跃检验&quot;">​</a></h1><div class="epigraph"><p>已实现方差把连续路径的积分波动和跳跃的平方和加在一起；相邻收益绝对值乘积的双幂次，在有限活动跳跃下仍收敛到积分波动，两者之差才是跳。</p><footer>—— Barndorff-Nielsen and Shephard, Power and Bipower Variation, Journal of Financial Econometrics 2004；检验理论见同作者 2006 年 Journal of Financial Econometrics 文</footer></div><p><a href="/quant/dcc">上一课</a>把条件协方差写成 \\(D_t R_t D_t\\)，更新二阶相关，不产生尾依赖，并点名与 Copula、EVT 互补。缺口是高频路径上的大缺口：有的是连续波动在开盘附近升高，有的是价格真的跳了。二次变差不区分二者。RV 估二次变差，双幂次变差在有限次跳跃下仍估连续部分的积分波动。本课写 BN–S 检验的对象、噪声如何冒充跳。不重写 DCC 的 \\(Q_t\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>半鞅分解把对数价格写成连续局部鞅加有限（或无穷）活动跳跃。积分波动 \\(IV=\\int\\sigma_u^2 du\\) 只来自连续部分；跳跃二次变差 \\(\\sum_{s\\le t}(\\Delta X_s)^2\\) 是另一项。期权的方差互换、连续 Delta 对冲、已实现核的对象常常是 \\(IV\\)，不是总二次变差。问题是：只用离散观测，如何检验当天（或某个格子）是否有跳，以及跳对当天方差的贡献有多大。</p><p>朴素做法是看是否有「很大」的格子收益。阈值依赖 \\(\\sigma\\)，而 \\(\\sigma\\) 日内季节性极强：开盘的 3σ 在统计上可能只是连续波动。必须用对跳跃稳健的波动尺度去标准化，而不是用当天的 RV——RV 已经含跳，阈值会被跳自己抬高，检验变保守。</p><h3 id="双幂次为何对有限跳稳健" tabindex="-1">双幂次为何对有限跳稳健 <a class="header-anchor" href="#双幂次为何对有限跳稳健" aria-label="Permalink to &quot;双幂次为何对有限跳稳健&quot;">​</a></h3><p>一次跳跃只污染一个格子收益。双幂次是相邻绝对值的乘积之和：跳所在格与邻居相乘，相对平方和，跳的贡献在网格变细时阶更低，概率上消失。三幂次、多幂次把同样逻辑推到更高阶，用于估积分四次变差（quarticity），给检验提供分母。无穷活动跳跃（许多小跳）会破坏这套分离，BN–S 的原定理针对有限活动，或跳的活动指数足够低。</p><p><span class="marginnote">「跳」在这里是半鞅的不连续点，不是财经标题里的「暴跌」。连续的随机波动可以在一小时内把 \\(\\sigma\\) 翻倍，路径仍连续，RV 与双幂次应接近。把宏观公告日一律叫做跳日，会把波动状态变量与不连续混成一个标签。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记第 \\(i\\) 个高频收益为 \\(r_i\\)。已实现方差 \\(\\mathrm{RV}=\\sum r_i^2\\)。已实现双幂次</p> \\[\\mathrm{BV}=\\mu_1^{-2}\\sum_{i=2}^{n}|r_{i-1}||r_i|,\\qquad \\mu_1=\\mathbb{E}|Z|=\\sqrt{2/\\pi}, \\]<p>\\(Z\\) 标准正态。无噪声、有限活动跳、网格 \\(\\Delta\\to 0\\) 时，\\(\\mathrm{BV}\\to_p IV\\)，而 \\(\\mathrm{RV}\\to_p IV+\\sum(\\Delta X)^2\\)。Barndorff-Nielsen–Shephard（2006）构造</p> \\[Z_{\\mathrm{J}}=\\frac{\\mathrm{RV}-\\mathrm{BV}}{\\sqrt{\\theta\\,\\Delta\\,\\mathrm{TP}}}, \\]<p>其中 \\(\\mathrm{TP}\\) 是已实现三幂次一类对 \\(\\int\\sigma^4\\) 的估计，\\(\\theta\\) 是由渐近理论给出的常数。无跳时 \\(Z_{\\mathrm{J}}\\) 渐近标准正态；有跳时分子趋于正的跳跃二次变差，检验趋于拒绝。Huang–Tauchen 的相对跳跃度量 \\(\\mathrm{RJ}=(\\mathrm{RV}-\\mathrm{BV})/\\mathrm{RV}\\) 把贡献写成比例，便于跨日比较。</p><p>Lee–Mykland 在每个格子上用局部窗口估瞬时 \\(\\sigma\\)，标准化 \\(|r_i|\\)，定位跳发生在哪一笔。Aït-Sahalia–Jacod 用不同幂次的已实现幂变差之比，对无穷活动也有理论。实务上日度「是否有跳」常用 BN–S 或 Huang–Tauchen；「哪一分钟跳」用 Lee–Mykland。</p><h3 id="噪声、隔夜与多重检验" tabindex="-1">噪声、隔夜与多重检验 <a class="header-anchor" href="#噪声、隔夜与多重检验" aria-label="Permalink to &quot;噪声、隔夜与多重检验&quot;">​</a></h3><p><a href="/quant/microstructure-noise">微观结构噪声</a> 抬高 RV，也破坏相邻乘积的极限。密采样上朴素 BN–S 会把噪声当跳。先预平均、已实现核或降频到噪声可忍受的格子，再做检验。隔夜缺口是日历上的跳，应单独一项，不要塞进日内 BV 的第一格。</p><p>一年 250 个交易日各做一次 5% 检验，期望就有十几个假跳日。阈值应用 Bonferroni 或假发现率，或把显著性放到 0.1%。检验功效对小跳弱：跳若只占当天 IV 的很小比例，\\(Z_{\\mathrm{J}}\\) 仍可能不拒绝。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连续半鞅的二次变差等于积分波动，离散 RV 多出来的交叉项与跳的平方在极限里分离：跳是稀疏的大项，连续部分是许多小项的平方和。双幂次用「不同格的乘积」避开同一格的平方，从而避开跳。分母里的 quarticity 来自连续部分的四次变差，描述无跳时 \\(\\mathrm{RV}-\\mathrm{BV}\\) 的波动；跳存在时你不再需要这个正态近似去做估计，只需要它在原假设下给临界值。</p><p>与<a href="/quant/iv-vs-rv">隐含 vs 已实现</a>的联系：方差互换复制在有跳时对准对数合约，与 \\(\\mathrm{RV}\\) 差跳跃凸性。BN–S 把 RV 拆成 BV 与跳，有助于解释 IV−RV 在公告日的裂口有多少来自跳溢价而不是连续方差溢价。</p><p><span class="marginnote">签名图上，噪声让 RV 在高频上翘；跳让 RV 在所有频率都抬一截（跳的平方不随网格变细而消失）。先看签名图再做 \\(Z_{\\mathrm{J}}\\)：上翘为主时先去噪声，平台抬高才像跳。</span></p><h3 id="从检验到建模" tabindex="-1">从检验到建模 <a class="header-anchor" href="#从检验到建模" aria-label="Permalink to &quot;从检验到建模&quot;">​</a></h3><p>检出跳之后，建模仍要选：有限活动复合泊松、无穷活动 Lévy，还是把公告做成确定时刻的条件跳。检验拒绝的是「连续半鞅加噪声可忽略」，并不指出跳的强度模型。把跳日从样本里删掉再估连续波动，是一种稳健做法，但会丢掉跳溢价的定价信息。对冲若假设连续路径，跳日的误差应由跳检验触发另一套限额，而不是把 \\(Z_{\\mathrm{J}}\\) 当成交易信号。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>有限样本里 BV 对连着两格都大的波动（开盘）会偏，季节性应先用日内模式除权。稀疏跳假设在闪崩式连续多笔大单上作假，Lee–Mykland 会标出一串「跳」，其实是短时流动性蒸发。无穷活动下 BN–S 的分离不干净，应换 Jacod 一类幂变差检验。</p><p>不要用日收益的绝对值阈值替代高频检验：日收益把跳与当天连续波动加总，无法分离。不要在未清洗的 tick 上算 BV：错价平方就是假跳。不要把显著 \\(Z_{\\mathrm{J}}\\) 解释为「可预测的跳」——检验是事后分解，不是提前预警。</p><p>多元时，共同跳与特异跳要分开：指数跳了并不意味每只成分都跳。已实现协方差的跳稳健版本（双幂次协方差等）对异步成交更脆弱，需与 <a href="/quant/irregular-sampling">Hayashi–Yoshida 一类同步问题</a>一起处理。</p><p><span class="marginnote">Barndorff-Nielsen–Shephard 的渐近是 \\(\\Delta\\to 0\\) 且无噪声。五分钟网格是噪声与偏差之间的工程点，不是定理里的采样。报告跳跃占比时写清网格、是否预平均、临界值如何对多重检验调整。</span></p>',30)),(t(),s(d,null,{default:r(()=>[h(i,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E9%AB%98%E9%A2%91%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20RV%5B%22RV%20%E2%86%92%20%E6%80%BB%E4%BA%8C%E6%AC%A1%E5%8F%98%E5%B7%AE%22%5D%0A%20%20Y%20--%3E%20BV%5B%22%E5%8F%8C%E5%B9%82%E6%AC%A1%20BV%20%E2%86%92%20%E7%A7%AF%E5%88%86%E6%B3%A2%E5%8A%A8%20IV%22%5D%0A%20%20RV%20--%3E%20D%5B%22RV%20%E2%88%92%20BV%22%5D%0A%20%20BV%20--%3E%20D%0A%20%20D%20--%3E%20Z%5B%22Z%20%E7%BB%9F%E8%AE%A1%E9%87%8F%20%2F%20Huang-Tauchen%20RJ%22%5D%0A%20%20Z%20--%3E%20J%5B%22%E6%8B%92%E7%BB%9D%3A%20%E8%B7%B3%E8%B7%83%E4%BA%8C%E6%AC%A1%E5%8F%98%E5%B7%AE%22%5D%0A%20%20Z%20--%3E%20C%5B%22%E4%B8%8D%E6%8B%92%E7%BB%9D%3A%20%E5%BD%93%E6%97%A5%E8%BF%91%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20Y%20--%3E%20N%5B%22%E5%99%AA%E5%A3%B0%E4%B8%8E%E5%AD%A3%E8%8A%82%E6%80%A7%E5%A4%84%E7%90%86%22%5D%0A%20%20N%20--%3E%20BV%0A%20%20N%20--%3E%20RV%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RV 估总二次变差，双幂次在有限活动跳跃下估连续积分波动，差为跳的贡献。</li><li>BN–S 用 quarticity 标准化该差，得日度跳跃检验；Lee–Mykland 定位格子，Aït-Sahalia–Jacod 覆盖更广的活动指数。</li><li>噪声、隔夜、日内季节性与多重检验会制造假跳；先清洗与降噪，再检验。</li><li>拒绝连续路径不等于给出跳的强度模型，也不等于可交易预测。</li><li>与无模型 IV 对照时，跳使对数合约与二次变差分家，应分开连续方差溢价与跳溢价。</li><li>出处：Barndorff-Nielsen and Shephard, <em>Journal of Financial Econometrics</em>, 2004 与 2006；相对份额见 Huang and Tauchen, 2005；定位见 Lee and Mykland, 2008；幂变差见 Aït-Sahalia and Jacod, 2009。</li></ul>',2))])}const q=n(p,[["render",E]]);export{f as __pageData,q as default};
